import json
import os

TODO_FILE = 'todos.json'

def load_todos():
    if not os.path.exists(TODO_FILE):
        return []
    with open(TODO_FILE, 'r') as file:
        return json.load(file)

def save_todos(todos):
    with open(TODO_FILE, 'w') as file:
        json.dump(todos, file, indent=4)

def add_todo(task):
    todos = load_todos()
    todos.append({"task": task, "completed": False})
    save_todos(todos)
    print(f"任务 '{task}' 已添加。")

def list_todos():
    todos = load_todos()
    if not todos:
        print("没有待办事项。")
        return
    for idx, todo in enumerate(todos, 1):
        status = "完成" if todo["completed"] else "未完成"
        print(f"{idx}. {todo['task']} - {status}")

if __name__ == "__main__":
    while True:
        print("\n待办事项管理器")
        print("1. 添加任务")
        print("2. 列出任务")
        print("3. 退出")
        choice = input("请选择操作: ")

        if choice == '1':
            task = input("请输入任务内容: ")
            add_todo(task)
        elif choice == '2':
            list_todos()
        elif choice == '3':
            break
        else:
            print("无效的选择，请重试。")

